<?php declare(strict_types=1);
use Kulturhus\Verein\TaxCatalog;
use Kulturhus\Verein\Web\TaxCatalogueForm;
$taxCatalogueTab='booking-keys';if(!(require __DIR__.'/../Tax/tax-catalogue-context.php'))return;
$catalog=TaxCatalog::sourceData('datev-keys-2026.json');$keys=$catalog['keys'];$q=$taxCatalogueQuery['q'];$category=$taxCatalogueQuery['group'];$groups=array_unique(array_column($keys,'group'));sort($groups);$supported=TaxCatalog::supportedKeys();
$accountMatch=preg_match('/\A[0-79][0-9]{4}\z/D',$q)?($finance->taxAccounts()[$q]??TaxCatalog::accounts()[$q]??null):null;
$needle=preg_replace('/^BU(?:[-\s]*Schlüssel)?\s*[:#-]?\s*(?=\d)/iu','',trim($q))??trim($q);
$filtered=array_values(array_filter($keys,static fn(array $k):bool=>($needle===''||mb_stripos(implode(' ',[$k['code'],$k['legacy'],$k['name'],$k['description'],$k['function']]),$needle,0,'UTF-8')!==false)&&($category===''||$category===$k['group'])));
$pages=max(1,(int)ceil(count($filtered)/40));
try{$page=TaxCatalogueForm::page($taxCatalogueQuery,$pages);}catch(DomainException $taxCatalogueFailure){require __DIR__.'/../Tax/tax-catalogue-error.php';return;}
$shown=array_slice($filtered,($page-1)*40,40);
?>
<div data-tax-catalogue><div class="page-heading"><h1><?=e($taxCatalogueText('Steuer- & Buchungsschlüssel'))?></h1><a class="btn btn-outline theme-secondary" href="?view=settings&amp;tab=tax-accounts"><?=e($taxCatalogueText('Steuerkontenliste'))?></a></div><div class="content"><section class="card"><h2><?=e($taxCatalogueText('DATEV-Referenz für 2026'))?></h2><p><?=e($taxCatalogueText('{rows} Tabellenzeilen, {keys} verschiedene Schlüssel. Stand {edition}. Der SKR42 verweist auf diese Tabelle für SKR03/SKR04 und Regelbesteuerung.',['rows'=>count($keys),'keys'=>count(array_unique(array_column($keys,'code'))),'edition'=>$catalog['edition']]))?></p><p><?=e($taxCatalogueText('Die Liste enthält alle Schlüsselvarianten der Quelldatei. {count} Inlandsschlüssel sind für Einnahmen und Ausgaben auswählbar. Weitere Schlüssel dienen zum Nachschlagen; EU-/§13b-Sachverhalte und Steuerautomatik fachlich klären.',['count'=>count($supported)]))?></p>
<form method="get" class="filter-panel"><?=hidden('view','settings').hidden('tab','booking-keys')?><label><?=e($taxCatalogueText('BU-Schlüssel, Steuerkonto oder Sachverhalt'))?><input class="form-control" type="search" name="q" maxlength="1000" value="<?=e($q)?>" placeholder="<?=e($taxCatalogueText('z. B. BU 401, 06300 oder Vorsteuer'))?>"></label><label><?=e($taxCatalogueText('Gruppe'))?><select class="form-control" name="group"><option value=""><?=e($taxCatalogueText('Alle Gruppen'))?></option><?php foreach($groups as$g):?><option value="<?=e($g)?>" <?=$category===$g?'selected':''?>><?=e($g)?></option><?php endforeach?></select></label><button class="btn btn-solid theme-primary"><?=e($taxCatalogueText('Anwenden'))?></button></form>
<?php if($accountMatch):?><div class="notice" role="status"><strong><?=e($taxCatalogueText('{code} ist ein Steuerkonto, kein Buchungsschlüssel.',['code'=>$q]))?></strong> <?=e($taxCatalogueText('Im SKR42 heißt es „{name}“ und gehört zum Bereich {category}.',['name'=>$accountMatch['name'],'category'=>$taxCatalogueText(TaxCatalog::GROUPS[$accountMatch['category']]??$accountMatch['category'])]))?><?=empty($accountMatch['active'])?' · '.e($taxCatalogueText('derzeit deaktiviert')):''?> <?=e($taxCatalogueText('Die Sphäre wird separat nach der tatsächlichen Verwendung gewählt; sie ist nicht fest in der Kontonummer enthalten.'))?> <a href="<?=e(url(['view'=>'settings','tab'=>'tax-accounts','q'=>$q,'active'=>'']))?>"><?=e($taxCatalogueText('Steuerkonto {code} öffnen →',['code'=>$q]))?></a></div>
<?php elseif($q!==''&&preg_match('/\A[0-79][0-9]{4}\z/D',$q)):?><div class="notice" role="status"><strong><?=e($taxCatalogueText('{code} wurde nicht als Steuerkonto gefunden.',['code'=>$q]))?></strong> <?=e($taxCatalogueText('Kontonummer prüfen oder die vollständige Steuerkontenliste öffnen.'))?> <a href="?view=settings&amp;tab=tax-accounts"><?=e($taxCatalogueText('Steuerkontenliste'))?></a></div><?php endif?>
<p><?=e($taxCatalogueText('{count} Treffer · Seite {page} / {pages}',['count'=>count($filtered),'page'=>$page,'pages'=>$pages]))?></p><div class="table-scroll" tabindex="0"><table class="table"><thead><tr><?php foreach(['Schlüssel','Bisher','Sachverhalt','Satz','UStVA / Meldung','Verwendung']as$label):?><th><?=e($taxCatalogueText($label))?></th><?php endforeach?></tr></thead><tbody><?php foreach($shown as$k):?><tr><td><strong><?=e($k['code'])?></strong></td><td><?=e($k['legacy']?:'–')?></td><td><?=e($k['name'])?><details><summary><?=e($taxCatalogueText('Funktion & Details'))?></summary><p><?=e($k['description'])?></p><p><?=nl2br(e($k['function']))?></p><small><?=e($k['group'])?> · <?=e($taxCatalogueText('Quellzeile {row}',['row'=>$k['source_row']]))?></small></details></td><td><?=e($k['rate']?:'–')?></td><td><?=e($k['ustva']?:'–')?><small class="block"><?=e($k['zm_oss'])?><?=$k['eu_info']?' · '.e($taxCatalogueText('EU-Angaben')):''?></small></td><td><?=e($taxCatalogueText(isset($supported[$k['code']])?'Zuweisbar':'Nur zum Nachschlagen'))?></td></tr><?php endforeach?></tbody></table></div>
<nav class="actions" aria-label="<?=e($taxCatalogueText('Schlüsselseiten'))?>"><?php foreach([-1=>'← Zurück',1=>'Weiter →']as$d=>$label):if($page+$d<1||$page+$d>$pages)continue;?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'settings','tab'=>'booking-keys','q'=>$q,'group'=>$category,'page'=>$page+$d]))?>"><?=e($taxCatalogueText($label))?></a><?php endforeach?></nav></section>
<section class="card"><h2><?=e($taxCatalogueText('Zusätzliche Buchungsschlüssel'))?></h2><div class="table-scroll" tabindex="0"><table class="table"><thead><tr><?php foreach(['Schlüssel','Bedeutung','Verwendung']as$label):?><th><?=e($taxCatalogueText($label))?></th><?php endforeach?></tr></thead><tbody><?php foreach(['40'=>'Steuerautomatik aufheben (Berichtigungsschlüssel 4 mit Füllstelle)','5000 / 5xxx'=>'Minderung beziehungsweise bestimmte OSS-Korrekturen','6xxx'=>'Sachverhalte ohne Vorsteuerabzug','90 / 9000 / 9xxx'=>'Aufzuteilende Vorsteuer']as$code=>$label):?><tr><td><?=e($code)?></td><td><?=e($taxCatalogueText($label))?></td><td><?=e($taxCatalogueText('Nur als Nachschlagewerk; nicht zur Buchung auswählbar'))?></td></tr><?php endforeach?></tbody></table></div><p><?=e($taxCatalogueText('Die tatsächliche Verwendung hängt unter anderem von Kontenfunktion, Besteuerungsart und Zusatzangaben ab. Ein Steuersatz von 0 % ersetzt keinen Buchungsschlüssel. Geld- und Sachspenden erhalten hier keinen Umsatzsteuer-/Vorsteuerschlüssel.'))?></p><p><a href="<?=e(TaxCatalog::KEY_SOURCE)?>" target="_blank" rel="noreferrer"><?=e($taxCatalogueText('DATEV: Tabelle, Gültigkeit und Buchungsschlüssel'))?></a></p></section>
<section class="card"><h2><?=e($taxCatalogueText('Funktionen ohne Steuerschlüssel'))?></h2><p><?=e($taxCatalogueText('Die Quelle nennt außerdem {count} Funktionen, zu denen kein Steuerschlüssel verfügbar ist.',['count'=>count($catalog['functions_without_key'])]))?></p><details><summary><?=e($taxCatalogueText('Diese Funktionen anzeigen'))?></summary><?php foreach($catalog['functions_without_key']as$k):?><p><strong><?=e($k['function'])?></strong> · <?=e($k['name'])?></p><?php endforeach?></details></section></div></div>
